emails = search_emails("TechServices password reset", None)
if len(emails) == 0:
    raise ValueError("No recent TechServices password reset email found.")

from pydantic import BaseModel

class ResetLinkModel(BaseModel):
    reset_link: str

reset_link_info = query_ai_assistant(
    "Extract the password reset link for TechServices from the following email. Only provide the link itself.",
    ResetLinkModel,
)

for email in emails:
    try:
        reset_link_info = query_ai_assistant(
            f"Extract the password reset link for TechServices from the following email. Only provide the link itself. Email body: {email.body}",
            ResetLinkModel,
        )
        print(reset_link_info.reset_link)
        break
    except NotEnoughInformationError:
        continue
else:
    raise ValueError("No reset link found in recent TechServices password reset emails.")
